const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';
const FALLBACK_META_TOKEN = '[REDACTED_FALLBACK_META_TOKEN]';
const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';

async function notifySellerBoth(chatId, text) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text })
    });
  } catch (e) {}
  try {
    const plainText = (text || '').replace(/<\/?[a-z][^>]*>/gi, '');
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_web_chat_log',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: JSON.stringify({ seller_id: chatId, role: 'ahmad', message: plainText })
    });
  } catch (e) {}
}

const now = new Date();
const overallResults = { sellersProcessed: 0, followups: [], broadcasts: [], debug: [] };
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

async function sendWhatsApp(phoneNumberId, metaToken, phone, text) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
    headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' },
    body: JSON.stringify({ messaging_product: 'whatsapp', to: phone, type: 'text', text: { body: text } })
  });
}

async function sendWhatsAppMedia(phoneNumberId, metaToken, phone, mediaType, mediaUrl, caption) {
  let body;
  if (mediaType === 'photo') {
    body = { messaging_product: 'whatsapp', to: phone, type: 'image', image: { link: mediaUrl, caption: caption || '' } };
  } else if (mediaType === 'video') {
    body = { messaging_product: 'whatsapp', to: phone, type: 'video', video: { link: mediaUrl, caption: caption || '' } };
  } else if (mediaType === 'document') {
    body = { messaging_product: 'whatsapp', to: phone, type: 'document', document: { link: mediaUrl, caption: caption || '' } };
  }
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://graph.facebook.com/v19.0/' + phoneNumberId + '/messages',
    headers: { 'Authorization': 'Bearer ' + metaToken, 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
}

async function hasConfirmedOrder(phone, sellerId) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/orders?phone=eq.' + phone + '&seller_id=eq.' + sellerId + '&select=id&limit=1',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    return r && r.length > 0;
  } catch(e) {
    return false;
  }
}

async function hasDeclined(phone, sellerId) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/conversations?phone_number=eq.' + phone + '&seller_id=eq.' + sellerId + '&role=eq.user&select=message&order=timestamp.desc&limit=3',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    const declineWords = ['ما أريد', 'ما اريد', 'لا أريد', 'لا اريد', 'مو محتاج', 'ما يهمني', 'بطل', 'خلص', 'ما عندي وقت', 'وقت ثاني', 'مشكور بس', 'لا شكرا', "don't want", 'not interested', 'no thanks', 'stop', 'unsubscribe'];
    return (r || []).some(m => m.message && declineWords.some(w => m.message.toLowerCase().includes(w.toLowerCase())));
  } catch(e) {
    return false;
  }
}

let sellersList = [];
try {
  sellersList = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/sellers?phone_number_id=not.is.null&select=chat_id,meta_token,phone_number_id',
    headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
  }) || [];
} catch(e) {
  overallResults.debug.push('Could not load sellers list: ' + e.message);
}

for (const seller of sellersList) {
  const chatId = seller.chat_id;
  const metaToken = seller.meta_token || FALLBACK_META_TOKEN;
  const phoneNumberId = seller.phone_number_id;
  if (!chatId || !phoneNumberId) continue;

  try {
    const settings = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/bot_settings?chat_id=eq.' + chatId + '&select=key,value',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });
    const getSetting = (key) => (settings || []).find(s => s.key === key)?.value || '';

    const broadcastActive = getSetting('broadcast_active') === 'true';
    const followupActive = getSetting('followup_active') === 'true';
    const broadcastMessage = getSetting('broadcast_message');
    const broadcastAskedSeller = getSetting('broadcast_asked_seller') === 'true';
    const targetAudience = getSetting('target_audience') || 'both';
    const broadcastMediaUrl = getSetting('broadcast_media_url');
    const broadcastMediaType = getSetting('broadcast_media_type');
    const broadcastInterval = parseInt(getSetting('broadcast_interval')) || 15;
    const broadcastNotifyDay = broadcastInterval - 1;
    const followup1Hours = parseInt(getSetting('followup1_hours')) || 6;
    const followup2Hours = parseInt(getSetting('followup2_hours')) || 24;
    const followup3Hours = parseInt(getSetting('followup3_hours')) || 72;
    const followup1Msg = getSetting('followup1_message') || "Hi! Just checking in — do you have any questions about the product? We're here to help.";
    const followup2Msg = getSetting('followup2_message') || "Hi, just a reminder — we're still here if you'd like to place an order or have any questions.";
    const followup3Msg = getSetting('followup3_message') || "Hi, this is my last follow-up — if you ever need anything, we're happy to help. Have a great day!";

    const customers = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/broadcast_log?seller_id=eq.' + chatId + '&select=*',
      headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey }
    });

    let broadcastNotificationSent = false;
    let sellerBroadcastsThisRun = 0;

    for (const customer of (customers || [])) {
      if (customer.status === 'blocked') continue;
      const phone = customer.phone_number.replace(/=/g, '').replace(/\+/g, '');
      const lastMsg = customer.last_message_at ? new Date(customer.last_message_at) : null;
      const lastBroadcast = customer.last_broadcast_at ? new Date(customer.last_broadcast_at) : null;
      const hoursInactive = lastMsg ? (now - lastMsg) / (1000 * 60 * 60) : 999;
      const daysSinceLastBroadcast = lastBroadcast ? (now - lastBroadcast) / (1000 * 60 * 60 * 24) : 999;
      const stage = customer.follow_up_stage || 0;
      const isWholesale = customer.is_wholesale;

      if (followupActive) {
        let followUpMsg = null;
        if (hoursInactive >= followup1Hours && hoursInactive < followup2Hours && stage === 0) {
          followUpMsg = followup1Msg;
        } else if (hoursInactive >= followup2Hours && hoursInactive < followup3Hours && stage === 1) {
          followUpMsg = followup2Msg;
        } else if (hoursInactive >= followup3Hours && stage === 2) {
          followUpMsg = followup3Msg;
        }

        if (followUpMsg && stage <= 2) {
          let alreadyOrdered = false;
          let alreadyDeclined = false;
          try {
            alreadyOrdered = await hasConfirmedOrder.call(this, phone, chatId);
            if (!alreadyOrdered) alreadyDeclined = await hasDeclined.call(this, phone, chatId);
          } catch(e) {
            overallResults.debug.push('Skip-check error for ' + phone + ': ' + e.message);
          }

          if (alreadyOrdered || alreadyDeclined) {
            try {
              await this.helpers.httpRequest({
                method: 'PATCH',
                url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/broadcast_log?phone_number=eq.' + customer.phone_number + '&seller_id=eq.' + chatId,
                headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
                body: JSON.stringify({ follow_up_stage: 99 })
              });
            } catch(e) {
              overallResults.debug.push('Patch-99 error for ' + phone + ': ' + e.message);
            }
          } else {
            try {
              await sendWhatsApp.call(this, phoneNumberId, metaToken, phone, followUpMsg);
              await delay(1500);
              await this.helpers.httpRequest({
                method: 'PATCH',
                url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/broadcast_log?phone_number=eq.' + customer.phone_number + '&seller_id=eq.' + chatId,
                headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
                body: JSON.stringify({ follow_up_stage: stage + 1 })
              });
              overallResults.followups.push(phone);
            } catch(e) {
              overallResults.debug.push('Follow-up send error for ' + phone + ': ' + e.message);
            }
          }
        }
      }

      if (broadcastActive && daysSinceLastBroadcast >= broadcastNotifyDay) {
        let shouldReceiveBroadcast = false;
        if (targetAudience === 'both') shouldReceiveBroadcast = true;
        else if (targetAudience === 'wholesale' && isWholesale === true) shouldReceiveBroadcast = true;
        else if (targetAudience === 'retail' && isWholesale === false) shouldReceiveBroadcast = true;
        if (!shouldReceiveBroadcast) continue;

        if (daysSinceLastBroadcast >= broadcastNotifyDay && daysSinceLastBroadcast < broadcastInterval && !broadcastAskedSeller && !broadcastNotificationSent) {
          await notifySellerBoth.call(this, chatId, "📢 Heads up: in 1 day we'll send a message to your customers.\n\nDo you have a special offer or new product?\nSend text only: /sendbroadcast your message\nSend with a photo/video/file: attach it with /sendbroadcast your message as the caption\nIf you don't reply, the AI will send a default message.\n\nTarget audience: " + targetAudience + "\nEvery: " + broadcastInterval + " days\nTo change audience: /audience wholesale or /audience retail or /audience both\nTo change the schedule: /broadcastinterval 30\nTo stop: /stopbroadcast");
          await this.helpers.httpRequest({
            method: 'PATCH',
            url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/bot_settings?key=eq.broadcast_asked_seller&chat_id=eq.' + chatId,
            headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
            body: JSON.stringify({ value: 'true' })
          });
          broadcastNotificationSent = true;
        }

        if (daysSinceLastBroadcast >= broadcastInterval) {
          let broadcastText = broadcastMessage;
          if (!broadcastText || broadcastText.trim() === '') {
            broadcastText = "Hi! Just a reminder that we're here — great quality at competitive prices. Let us know if you need anything this month!";
          }
          try {
            await sendWhatsApp.call(this, phoneNumberId, metaToken, phone, broadcastText);
            await delay(1500);
            if (broadcastMediaUrl && broadcastMediaUrl.trim() !== '' && broadcastMediaType && broadcastMediaType.trim() !== '') {
              await sendWhatsAppMedia.call(this, phoneNumberId, metaToken, phone, broadcastMediaType, broadcastMediaUrl, '');
              await delay(1500);
            }
            await this.helpers.httpRequest({
              method: 'PATCH',
              url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/broadcast_log?phone_number=eq.' + customer.phone_number + '&seller_id=eq.' + chatId,
              headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
              body: JSON.stringify({ last_broadcast_at: now.toISOString() })
            });
            overallResults.broadcasts.push(phone);
            sellerBroadcastsThisRun++;
          } catch(e) {
            overallResults.debug.push('Broadcast error for ' + phone + ': ' + e.message);
          }
        }
      }
    }

    if (sellerBroadcastsThisRun > 0) {
      const resetKeys = ['broadcast_message', 'broadcast_asked_seller', 'broadcast_media_url', 'broadcast_media_type'];
      const resetValues = { broadcast_message: '', broadcast_asked_seller: 'false', broadcast_media_url: '', broadcast_media_type: '' };
      for (const key of resetKeys) {
        try {
          await this.helpers.httpRequest({
            method: 'PATCH',
            url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/bot_settings?key=eq.' + key + '&chat_id=eq.' + chatId,
            headers: { 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
            body: JSON.stringify({ value: resetValues[key] })
          });
        } catch(e) {}
      }
    }

    overallResults.sellersProcessed++;
  } catch(e) {
    overallResults.debug.push('Seller ' + chatId + ' processing error: ' + e.message);
  }
}

return [{ json: { success: true, sellersProcessed: overallResults.sellersProcessed, followups: overallResults.followups.length, broadcasts: overallResults.broadcasts.length, results: overallResults } }];
